      "evidence": [
        {"source": "schematic", "quote": "Page 1 'WATER LEVEL SENSOR/SWITCHES': PR1 'LiDAR' pins VCC/SDA/SCL wired to H1 with '+5V', 'I2C_SDA', 'I2C_SCL' and 'EZO_PDIS' labels"},
